tr.widgetCss:
.widget-item {
    display: flex;
}

.widget-item.widget-1 {
    flex-direction: row;
}

.widget-item.widget-2 {
    flex-direction: row-reverse;
}
@media (max-width: 767px) {
    .widget-item {
        flex-direction: column;
    }
}

